16	/**
17	 * Grouped "Control panel" tab on the server detail page — a cPanel/Plesk-style
18	 * manager for the customer's own VPS, themed to match Nxeon. Keeps the four
19	 * bundles behind a single main tab with lightweight inner tabs so the page stays
20	 * readable. Each panel loads its own data client-side (loading/empty/error
21	 * states throughout) via the sandbox-gated server actions.
22	 */
23	export function ControlPanel({ serverId, running }: { serverId: string; running: boolean }) {
24	  const [tab, setTab] = useState<string>("websites");
25	
26	  return (
27	    <div className="space-y-6">
28	      <div className="flex flex-wrap gap-1.5">
29	        {SUBTABS.map((t) => {
30	          const active = tab === t.key;
31	          return (
32	            <button
33	              key={t.key}
34	              type="button"
35	              onClick={() => setTab(t.key)}
36	              className={`rounded-xl px-3.5 py-1.5 text-sm font-medium transition-colors ${
37	                active
38	                  ? "bg-white/[0.08] text-white ring-1 ring-inset ring-brand-500/40"
39	                  : "text-slate-400 hover:bg-white/[0.04] hover:text-white"
40	              }`}
41	            >
42	              {t.label}
43	            </button>
44	          );
45	        })}
46	      </div>
47	
48	      <div className="animate-fade-up">
49	        {tab === "websites" && <WebsitesPanel serverId={serverId} running={running} />}
50	        {tab === "databases" && <DatabasesPanel serverId={serverId} running={running} />}
51	        {tab === "apps" && <AppsPanel serverId={serverId} running={running} />}
52	        {tab === "services" && <CronServicesPanel serverId={serverId} running={running} />}
53	      </div>
54	    </div>
55	  );
56	}
