1	"use server";
2	
3	/**
4	 * Control panel — Websites & PHP.
5	 *
6	 * Add a website (nginx server block + docroot under /var/www/<domain>), pick a
7	 * PHP-FPM version, enable/disable, one-click Let's Encrypt SSL, and subdomains.
8	 * List/edit/delete. Every op is ownership-checked + rate-limited and respects
9	 * the "no panel work while a lifecycle job is in flight / server not running"
10	 * invariant. The real SSH work runs in worker/websites.ts (sandbox-gated); the
11	 * lists here are served straight from the Website table.
12	 */
13	import { revalidatePath } from "next/cache";
14	import { db } from "./db";
15	import { requireUser } from "./auth";
16	import { checkRateLimit } from "./rate-limit";
17	import { DOMAIN_RE, PHP_VERSION_RE } from "./ssh-exec";
18	import { PHP_VERSIONS, type WebsiteRow } from "./cpanel-types";
19	import { pointHostnameToIp } from "./cloudflare-point";
20	import { readStoredCloudflare } from "./cloudflare-oauth";
21	
22	type Result = { ok: true } | { ok: false; error: string };
23	type CreateResult = { ok: true; id: string } | { ok: false; error: string };
24	type PointResult = { ok: true; message: string } | { ok: false; error: string };
25	
26	/** Job types that must not overlap with panel work (lifecycle / destructive). */
27	const EXCLUSIVE_JOBS = [
28	  "PROVISION",
29	  "REINSTALL",
30	  "DELETE",
31	  "RESIZE",
32	  "SUSPEND",
33	  "UNSUSPEND",
34	  "SNAPSHOT_ROLLBACK",
35	  "BACKUP_RESTORE",
36	  // A disk expansion runs growpart/resize2fs over SSH inside the guest; keep the
37	  // control-panel operations out of the way while the root filesystem is resized.
38	  "DISK_EXPAND",
39	] as const;
40	
41	async function ownedServer(serverId: string) {
42	  const user = await requireUser();
43	  const server = await db.server.findUnique({
44	    where: { id: serverId },
45	    select: { id: true, userId: true, status: true, hostname: true },
46	  });
47	  if (!server) throw new Error("Not found");
48	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
49	  return { user, server };
50	}
51	
52	async function ownedWebsite(id: string) {
53	  const user = await requireUser();
54	  const site = await db.website.findUnique({
55	    where: { id },
56	    include: { server: { select: { id: true, userId: true, status: true } } },
57	  });
58	  if (!site) throw new Error("Not found");
59	  if (site.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
60	  return { user, site };
61	}
62	
63	function throttle(userId: string, op: string, max: number): string | null {
64	  const rl = checkRateLimit(`cpanel:web:${op}:${userId}`, { max, windowMs: 60_000 });
65	  return rl.ok ? null : `Too many requests — retry in ${rl.retryAfterSec}s.`;
66	}
67	
68	/** Reject if a lifecycle/destructive job is queued or running on the server. */
69	async function lifecycleBusy(serverId: string): Promise<boolean> {
70	  const n = await db.job.count({
71	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] }, type: { in: EXCLUSIVE_JOBS as any } },
72	  });
73	  return n > 0;
74	}
75	
76	function safeError(err: unknown): string {
77	  const msg = err instanceof Error ? err.message : String(err);
78	  if (msg === "Not found" || msg === "Forbidden") return "Server not found.";
79	  return msg.slice(0, 300);
80	}
81	
82	function rowOut(w: {
83	  id: string;
84	  domain: string;
85	  docRoot: string;
86	  phpVersion: string | null;
87	  ssl: boolean;
88	  enabled: boolean;
89	  isSubdomain: boolean;
90	  parentDomain: string | null;
91	  appSlug: string | null;
92	  status: string;
93	  error: string | null;
94	  createdAt: Date;
95	}): WebsiteRow {
96	  return {
97	    id: w.id,
98	    domain: w.domain,
99	    docRoot: w.docRoot,
100	    phpVersion: w.phpVersion,
101	    ssl: w.ssl,
102	    enabled: w.enabled,
103	    isSubdomain: w.isSubdomain,
104	    parentDomain: w.parentDomain,
105	    appSlug: w.appSlug,
106	    status: w.status,
107	    error: w.error,
108	    createdAt: w.createdAt.toISOString(),
109	  };
110	}
111	
112	// ---------------------------------------------------------------------------
113	
114	export async function listWebsites(
115	  serverId: string
116	): Promise<
117	  | { ok: true; websites: WebsiteRow[]; serverIp: string | null; cloudflareConnected: boolean }
118	  | { ok: false; error: string }
119	> {
120	  try {
121	    const { user, server } = await ownedServer(serverId);
122	    const sites = await db.website.findMany({
123	      where: { serverId: server.id },
124	      orderBy: { createdAt: "desc" },
125	    });
126	    return {
127	      ok: true,
128	      websites: sites.map(rowOut),
129	      // Both feed the "point DNS at this server" control in the panel.
130	      serverIp: await publicIpOf(server.id),
131	      cloudflareConnected: readStoredCloudflare(user.cloudflareTokenEnc) !== null,
132	    };
133	  } catch (err) {
134	    return { ok: false, error: safeError(err) };
135	  }
136	}
137	
138	/**
139	 * The address a customer's domain should resolve to for this server: its
140	 * dedicated failover IP when one is attached, otherwise the server's own public
141	 * IPv4. Null while the server is still being provisioned.
142	 */
143	async function publicIpOf(serverId: string): Promise<string | null> {
144	  const row = await db.server.findUnique({
145	    where: { id: serverId },
146	    select: { ipAddress: true, dedicatedIp: { select: { address: true } } },
147	  });
148	  return row?.dedicatedIp?.address ?? row?.ipAddress ?? null;
149	}
150	
151	/**
152	 * Point a website's hostname at the server it lives on, by upserting an A record
153	 * in the customer's Cloudflare zone.
154	 *
155	 * Guards: requireUser + website ownership (via ownedWebsite), rate-limited like
156	 * its neighbours, and the hostname is taken from OUR Website row — never from
157	 * client input — then re-validated inside pointHostnameToIp.
158	 *
159	 * The record is written PROXIED = FALSE (DNS-only). That is deliberate: the name
160	 * must resolve to this server so Let's Encrypt's HTTP-01 challenge reaches
161	 * certbot on the box. Behind Cloudflare's proxy the challenge is answered at
162	 * their edge and SSL issuance fails.
163	 */
164	export async function pointWebsiteDns(id: string): Promise<PointResult> {
165	  try {
166	    const { user, site } = await ownedWebsite(id);
167	    const limited = throttle(user.id, "dns", 12);
168	    if (limited) return { ok: false, error: limited };
169	
170	    const ip = await publicIpOf(site.serverId);
171	    if (!ip) {
172	      return {
173	        ok: false,
174	        error: "This server doesn't have a public IP yet — try again once it has finished provisioning.",
175	      };
176	    }
177	
178	    const res = await pointHostnameToIp({
179	      user: { id: user.id, cloudflareTokenEnc: user.cloudflareTokenEnc },
180	      hostname: site.domain,
181	      ip,
182	    });
183	    if (!res.ok) return { ok: false, error: res.error };
184	
185	    await db.auditLog.create({
186	      data: {
187	        userId: user.id,
188	        action: "cpanel.website.dns",
189	        detail: `${site.domain} A → ${ip}${res.simulated ? " (sandbox)" : ""}`,
190	      },
191	    });
192	    revalidatePath(`/dashboard/servers/${site.serverId}`);
193	
194	    return {
195	      ok: true,
196	      message: res.simulated
197	        ? `Sandbox: pretended to point ${res.hostname} at ${ip} (DNS-only). No record was sent to Cloudflare.`
198	        : `${res.hostname} now points at ${ip} (A record ${res.action}, DNS-only). DNS changes can take a few minutes to reach everyone.`,
199	    };
200	  } catch (err) {
201	    return { ok: false, error: safeError(err) };
202	  }
203	}
204	
205	export async function createWebsite(
206	  serverId: string,
207	  domainInput: string,
208	  phpVersion: string | null,
209	  parentDomain?: string
210	): Promise<CreateResult> {
211	  try {
212	    const { user, server } = await ownedServer(serverId);
213	    const limited = throttle(user.id, "create", 10);
214	    if (limited) return { ok: false, error: limited };
215	    if (server.status !== "RUNNING") return { ok: false, error: "The server must be running to add a website." };
216	    if (await lifecycleBusy(server.id))
217	      return { ok: false, error: "Another server operation is in progress — try again shortly." };
218	
219	    const domain = String(domainInput ?? "").toLowerCase().trim().replace(/\.$/, "");
220	    if (!DOMAIN_RE.test(domain))
221	      return { ok: false, error: "Enter a valid domain (e.g. example.com or blog.example.com)." };
222	
223	    const php = phpVersion ? String(phpVersion).trim() : null;
224	    if (php && (!PHP_VERSION_RE.test(php) || !(PHP_VERSIONS as readonly string[]).includes(php)))
225	      return { ok: false, error: "Choose a supported PHP version." };
226	
227	    const isSubdomain = !!parentDomain;
228	    const parent = parentDomain ? String(parentDomain).toLowerCase().trim() : null;
229	    if (parent && !DOMAIN_RE.test(parent)) return { ok: false, error: "Invalid parent domain." };
230	
231	    const existing = await db.website.findFirst({ where: { serverId: server.id, domain } });
232	    if (existing) return { ok: false, error: `A website for ${domain} already exists on this server.` };
233	
234	    const count = await db.website.count({ where: { serverId: server.id } });
235	    if (count >= 50) return { ok: false, error: "Website limit reached (50 per server)." };
236	
237	    const docRoot = `/var/www/${domain}`;
238	    const site = await db.website.create({
239	      data: {
240	        userId: user.id,
241	        serverId: server.id,
242	        domain,
243	        docRoot,
244	        phpVersion: php,
245	        isSubdomain,
246	        parentDomain: parent,
247	        status: "PENDING",
248	      },
249	    });
250	    await db.job.create({ data: { type: "WEBSITE_CREATE", serverId: server.id, payload: { websiteId: site.id } } });
251	    await db.auditLog.create({
252	      data: { userId: user.id, action: "cpanel.website.create", detail: `${domain} on ${server.hostname}` },
253	    });
254	    revalidatePath(`/dashboard/servers/${serverId}`);
255	    return { ok: true, id: site.id };
256	  } catch (err) {
257	    return { ok: false, error: safeError(err) };
258	  }
259	}
260	
261	export async function toggleWebsite(id: string): Promise<Result> {
262	  try {
263	    const { user, site } = await ownedWebsite(id);
264	    const limited = throttle(user.id, "toggle", 20);
265	    if (limited) return { ok: false, error: limited };
266	    if (site.status === "PENDING" || site.status === "DELETING")
267	      return { ok: false, error: "This website is still being set up." };
268	    await db.website.update({ where: { id }, data: { enabled: !site.enabled, status: "PENDING" } });
269	    await db.job.create({ data: { type: "WEBSITE_TOGGLE", serverId: site.serverId, payload: { websiteId: id } } });
270	    revalidatePath(`/dashboard/servers/${site.serverId}`);
271	    return { ok: true };
272	  } catch (err) {
273	    return { ok: false, error: safeError(err) };
274	  }
275	}
276	
277	export async function requestWebsiteSsl(id: string): Promise<Result> {
278	  try {
279	    const { user, site } = await ownedWebsite(id);
280	    const limited = throttle(user.id, "ssl", 10);
281	    if (limited) return { ok: false, error: limited };
282	    if (site.status !== "ACTIVE") return { ok: false, error: "The website must be active before enabling SSL." };
283	    if (site.ssl) return { ok: false, error: "SSL is already enabled for this website." };
284	    await db.job.create({ data: { type: "WEBSITE_SSL", serverId: site.serverId, payload: { websiteId: id } } });
285	    await db.auditLog.create({
286	      data: { userId: user.id, action: "cpanel.website.ssl", detail: site.domain },
287	    });
288	    revalidatePath(`/dashboard/servers/${site.serverId}`);
289	    return { ok: true };
290	  } catch (err) {
291	    return { ok: false, error: safeError(err) };
292	  }
293	}
294	
295	export async function deleteWebsite(id: string): Promise<Result> {
296	  try {
297	    const { user, site } = await ownedWebsite(id);
298	    const limited = throttle(user.id, "delete", 15);
299	    if (limited) return { ok: false, error: limited };
300	    if (site.appSlug)
301	      return { ok: false, error: "This site was created by a one-click app — remove it from the Apps tab." };
302	    await db.website.update({ where: { id }, data: { status: "DELETING" } });
303	    await db.job.create({ data: { type: "WEBSITE_DELETE", serverId: site.serverId, payload: { websiteId: id } } });
304	    await db.auditLog.create({
305	      data: { userId: user.id, action: "cpanel.website.delete", detail: site.domain },
306	    });
307	    revalidatePath(`/dashboard/servers/${site.serverId}`);
308	    return { ok: true };
309	  } catch (err) {
310	    return { ok: false, error: safeError(err) };
311	  }
312	}
