95	/**
96	 * Validate a cron command: length-bounded, no NUL / newline / control chars, no
97	 * comment-injection into the crontab block. The command is written to the far
98	 * side via a here-doc body (STDIN), never interpolated into a shell command, so
99	 * shell metacharacters inside it run in the user's OWN crontab as intended — but
100	 * we still forbid newlines (would forge extra crontab lines).
101	 */
102	function validateCommand(cmd: string): string {
103	  const c = String(cmd ?? "");
104	  if (c.trim().length === 0) throw new Error("A command is required.");
105	  if (c.length > MAX_CMD_LEN) throw new Error(`Command is too long (max ${MAX_CMD_LEN} chars).`);
106	  if (/[\x00-\x08\x0a-\x1f\x7f]/.test(c)) throw new Error("Command contains invalid control characters.");
107	  return c.trim();
108	}
