19	/**
20	 * Control-panel CRON_SYNC / SERVICE_ACTION handlers.
21	 *
22	 * Registered in worker/index.ts:
23	 *   CRON_SYNC:      cronSync,
24	 *   SERVICE_ACTION: serviceAction,
25	 *
26	 * CRON_SYNC rebuilds a single Nxeon-managed block in root's crontab from all of
27	 * the server's enabled CronJob rows (removing DELETING ones). The whole crontab
28	 * body is installed via `crontab -`'s STDIN, so user command lines are never
29	 * interpolated into a shell we run. Schedules are allowlist-validated.
30	 *
31	 * SANDBOX / non-ENABLE_REAL_CPANEL: no SSH — rows just settle to ACTIVE.
32	 */
33	
34	const REAL = !SANDBOX && process.env.ENABLE_REAL_CPANEL === "1";
35	const BEGIN = "# BEGIN NXEON CONTROL PANEL — managed block, do not edit";
36	const END = "# END NXEON CONTROL PANEL";
37	
38	async function notify(userId: string, title: string, body?: string, href?: string) {
39	  try {
40	    await db.notification.create({ data: { userId, title, body, href } });
41	  } catch (e) {
