123	/** Resolve + run a systemctl action for one of the fixed common services. */
124	async function runService(conn: Client, unit: string, action: string): Promise<void> {
125	  assertService(unit);
126	  assert((SERVICE_ACTIONS as readonly string[]).includes(action), `Unsupported action: ${action}`);
127	  let cmd: string;
128	  if (unit === "php-fpm") {
129	    // php-fpm is version-suffixed on Debian/Ubuntu; resolve the real unit name.
130	    cmd =
131	      `u=$(systemctl list-unit-files --no-legend 'php*-fpm.service' 2>/dev/null | awk '{print $1}' | head -n1); ` +
132	      `[ -n "$u" ] || u=php-fpm; systemctl ${action} "$u"`;
133	  } else if (unit === "mysql") {
134	    cmd = `systemctl ${action} mariadb 2>/dev/null || systemctl ${action} mysql`;
135	  } else {
136	    cmd = `systemctl ${action} ${shellQuote(unit)}`;
137	  }
138	  const r = await exec(conn, cmd, SETUP_TIMEOUT_MS);
139	  if (r.code !== 0) throw new Error(`${action} ${unit} failed: ${(r.stderr || r.stdout).trim().slice(0, 200)}`);
140	}
