142	export async function serviceAction(job: Job): Promise<void> {
143	  if (!job.serverId) throw new Error("service action: missing serverId");
144	  const p = (job.payload ?? {}) as { unit?: string; action?: string };
145	  const unit = String(p.unit ?? "");
146	  const action = String(p.action ?? "");
147	  assertService(unit);
148	  assert((SERVICE_ACTIONS as readonly string[]).includes(action), `Unsupported action: ${action}`);
149	
150	  const server = await db.server.findUnique({ where: { id: job.serverId }, select: { userId: true, hostname: true } });
151	
152	  try {
153	    if (REAL) {
154	      const s = await sshServer(job.serverId);
155	      await withServerSsh(s, async (conn) => runService(conn, unit, action));
156	    }
157	    if (server) {
158	      await notify(
159	        server.userId,
160	        `${action[0].toUpperCase()}${action.slice(1)}ed ${unit}`,
161	        REAL ? `${unit} was ${action}ed on ${server.hostname}.` : `${unit} ${action} (sandbox — no real VM was touched).`,
162	        `/dashboard/servers/${job.serverId}?tab=control panel`
163	      );
164	    }
165	  } catch (e: any) {
166	    const reason = String(e?.message ?? e).slice(0, 300);
167	    if (server) await notify(server.userId, `Could not ${action} ${unit}`, reason, `/dashboard/servers/${job.serverId}`);
168	    throw e; // let the worker mark the job FAILED/retry
169	  }
170	}
