305	  }
306	}
307	
308	/** Parse a client→server frame. Returns null for anything unrecognized. */
309	function parseClientMsg(raw: Buffer, isBinary: boolean): ClientMsg | null {
310	  if (isBinary) return null;
311	  let obj: unknown;
312	  try {
313	    obj = JSON.parse(raw.toString("utf8"));
314	  } catch {
315	    return null;
316	  }
317	  if (!obj || typeof obj !== "object") return null;
318	  const m = obj as Record<string, unknown>;
319	  if (m.type === "data" && typeof m.data === "string") {
320	    return { type: "data", data: m.data };
321	  }
322	  if (m.type === "resize") {
323	    return { type: "resize", cols: clampDim(m.cols, 80), rows: clampDim(m.rows, 24) };
324	  }
325	  return null;
326	}
327	
328	/**
329	 * Sandbox shell: a friendly simulated terminal. No SSH — just a banner and a
330	 * local echo of what the user types, so the whole UX works on staging.
331	 */
332	function startSandboxShell(
333	  ws: WebSocket,
334	  bump: () => void,
335	  shutdown: (reason: string, notify?: string) => void
336	): void {
337	  const nl = "\r\n";
338	  const prompt = "\x1b[32mnxeon-sandbox\x1b[0m:\x1b[34m~\x1b[0m# ";
339	  const banner =
340	    `\x1b[36mNxeon sandbox terminal\x1b[0m${nl}` +
341	    `This is a simulated shell on the staging environment — no real SSH` +
342	    ` connection is made.${nl}` +
343	    `Type anything and it will be echoed back. On production this is a real` +
344	    ` root shell where you can run \x1b[1mclaude\x1b[0m.${nl}${nl}`;
345	
346	  if (ws.readyState === WebSocket.OPEN) ws.send(banner + prompt);
347	
348	  let line = "";
349	  ws.on("message", (raw: Buffer, isBinary: boolean) => {
350	    bump();
351	    const msg = parseClientMsg(raw, isBinary);
352	    if (!msg || msg.type !== "data") return; // ignore resize in the sim
353	    for (const ch of msg.data) {
354	      if (ch === "\r" || ch === "\n") {
355	        let out = nl;
356	        if (line.trim()) out += `you typed: ${line}${nl}`;
357	        line = "";
358	        if (ws.readyState === WebSocket.OPEN) ws.send(out + prompt);
359	      } else if (ch === "\x7f" || ch === "\b") {
360	        if (line.length > 0) {
361	          line = line.slice(0, -1);
362	          if (ws.readyState === WebSocket.OPEN) ws.send("\b \b");
363	        }
364	      } else if (ch >= " ") {
365	        line += ch;
366	        if (ws.readyState === WebSocket.OPEN) ws.send(ch);
367	      }
368	    }
369	  });
370	
371	  // Keep the same guarantee that the socket eventually closes.
372	  void shutdown;
373	}
374	
375	process.on("SIGTERM", () => wss.close(() => process.exit(0)));
376	process.on("SIGINT", () => wss.close(() => process.exit(0)));
