1	#!/usr/bin/env node
2	/**
3	 * Nxeon in-browser VNC console — websocket relay.
4	 *
5	 * A tiny standalone process that bridges a browser noVNC websocket to a
6	 * Proxmox `vncwebsocket` endpoint. The browser never receives the Proxmox API
7	 * token or the raw VNC ticket — those arrive here inside an encrypted JWE
8	 * (issued by app/api/console/[serverId]/route.ts) which only this relay, which
9	 * shares AUTH_SECRET with the web app, can decrypt.
10	 *
11	 *   browser  ──ws──▶  console-proxy  ──wss──▶  Proxmox /vncwebsocket
12	 *            (noVNC)   (holds creds)           (VNC RFB stream)
13	 *
14	 * DEPENDENCIES: only Node built-ins (http, tls, crypto, url) + `jose` (already
15	 * a project dependency — used for JWE). The `ws` npm package is NOT required;
16	 * the WebSocket framing (server-accept handshake, client handshake, frame
17	 * encode/decode, masking, fragmentation, ping/pong) is implemented below.
18	 *
19	 * ENV (read from the same /opt/nxeon/.env as the web app):
20	 *   AUTH_SECRET          shared secret — must match the web app (required)
21	 *   CONSOLE_PROXY_PORT   listen port (default 8899)
22	 *   CONSOLE_PROXY_HOST   listen address (default 0.0.0.0)
23	 *
24	 * Run: node scripts/console-proxy.mjs
25	 */
26	
27	import http from "node:http";
28	import tls from "node:tls";
29	import { createHash, randomBytes } from "node:crypto";
30	import { jwtDecrypt } from "jose";
31	
32	const PORT = Number(process.env.CONSOLE_PROXY_PORT ?? 8899);
33	const HOST = process.env.CONSOLE_PROXY_HOST ?? "0.0.0.0";
34	const WS_GUID = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11";
35	
36	// 256-bit JWE key derived identically to the web app (lib route consoleKey()).
37	function consoleKey() {
38	  const secret = process.env.AUTH_SECRET;
39	  if (!secret) {
40	    console.error("[console-proxy] FATAL: AUTH_SECRET not set");
41	    process.exit(1);
42	  }
43	  return new Uint8Array(createHash("sha256").update(`nxeon-console:${secret}`).digest());
44	}
45	const KEY = consoleKey();
46	
47	// Single-use ticket tracking: jti -> expiry(ms). A ticket may be redeemed once.
48	const usedJti = new Map();
49	setInterval(() => {
50	  const now = Date.now();
51	  for (const [jti, exp] of usedJti) if (exp < now) usedJti.delete(jti);
52	}, 30_000).unref();
53	
54	/* ------------------------------------------------------------------ *
55	 *  Minimal WebSocket framing over a raw duplex socket.
56	 *  `maskOut`: true when we act as a WS *client* (browser→Proxmox side must
57	 *  mask per RFC 6455); false when we act as a WS *server* (frames to the
58	 *  browser must NOT be masked).
59	 * ------------------------------------------------------------------ */
60	class WsConn {
61	  constructor(socket, maskOut, name) {
62	    this.socket = socket;
63	    this.maskOut = maskOut;
64	    this.name = name;
65	    this.buf = Buffer.alloc(0);
66	    this.fragOpcode = 0;
67	    this.fragChunks = [];
68	    this._handler = null; // (opcode, payload:Buffer) => void
69	    this._pending = []; // messages received before a handler is bound
70	    this.onclose = null;
71	    this.closed = false;
72	
73	    socket.on("data", (chunk) => {
74	      this.buf = this.buf.length ? Buffer.concat([this.buf, chunk]) : chunk;
75	      try {
76	        this._parse();
77	      } catch (err) {
78	        console.error(`[console-proxy] frame parse error on ${name}:`, err.message);
79	        this.close();
80	      }
81	    });
82	    socket.on("close", () => this._fireClose());
83	    socket.on("error", () => this._fireClose());
84	  }
85	
86	  _fireClose() {
87	    if (this.closed) return;
88	    this.closed = true;
89	    if (this.onclose) this.onclose();
90	  }
91	
92	  /** Bind the message handler and flush anything buffered before it was set.
93	   *  Guards against dropping frames a peer sends before the other leg is up. */
94	  bind(handler) {
95	    this._handler = handler;
96	    const q = this._pending;
97	    this._pending = [];
98	    for (const [op, p] of q) handler(op, p);
99	  }
100	
101	  _emit(opcode, payload) {
102	    if (this._handler) this._handler(opcode, payload);
103	    else this._pending.push([opcode, payload]);
104	  }
105	
106	  _parse() {
107	    for (;;) {
108	      const b = this.buf;
109	      if (b.length < 2) return;
110	      const b0 = b[0];
111	      const b1 = b[1];
112	      const fin = (b0 & 0x80) !== 0;
113	      const opcode = b0 & 0x0f;
114	      const masked = (b1 & 0x80) !== 0;
115	      let len = b1 & 0x7f;
116	      let offset = 2;
117	      if (len === 126) {
118	        if (b.length < 4) return;
119	        len = b.readUInt16BE(2);
120	        offset = 4;
121	      } else if (len === 127) {
122	        if (b.length < 10) return;
123	        len = Number(b.readBigUInt64BE(2));
124	        offset = 10;
125	      }
126	      let maskKey;
127	      if (masked) {
128	        if (b.length < offset + 4) return;
129	        maskKey = b.subarray(offset, offset + 4);
130	        offset += 4;
131	      }
132	      const total = offset + len;
133	      if (b.length < total) return;
134	      let payload = Buffer.from(b.subarray(offset, total)); // copy — buf gets sliced
135	      if (masked) {
136	        for (let i = 0; i < payload.length; i++) payload[i] ^= maskKey[i & 3];
137	      }
138	      this.buf = b.subarray(total);
139	      this._handleFrame(fin, opcode, payload);
140	    }
141	  }
142	
143	  _handleFrame(fin, opcode, payload) {
144	    if (opcode === 0x8) {
145	      // close
146	      this.close();
147	      return;
148	    }
149	    if (opcode === 0x9) {
150	      // ping -> reply pong on same socket, and swallow
151	      this._send(0xa, payload);
152	      return;
153	    }
154	    if (opcode === 0xa) return; // pong -> ignore
155	
156	    // data (0x1 text, 0x2 binary) or continuation (0x0)
157	    if (opcode === 0x0) {
158	      this.fragChunks.push(payload);
159	      if (fin) {
160	        const full = Buffer.concat(this.fragChunks);
161	        const op = this.fragOpcode || 0x2;
162	        this.fragChunks = [];
163	        this.fragOpcode = 0;
164	        this._emit(op, full);
165	      }
166	      return;
167	    }
168	    if (fin) {
169	      this._emit(opcode, payload);
170	    } else {
171	      this.fragOpcode = opcode;
172	      this.fragChunks = [payload];
173	    }
174	  }
175	
176	  /** Encode + write a single (unfragmented) frame. */
177	  _send(opcode, payload) {
178	    if (this.closed || this.socket.destroyed) return;
179	    const len = payload.length;
180	    let header;
181	    if (len < 126) {
182	      header = Buffer.alloc(2);
183	      header[1] = len;
184	    } else if (len < 65536) {
185	      header = Buffer.alloc(4);
186	      header[1] = 126;
187	      header.writeUInt16BE(len, 2);
188	    } else {
189	      header = Buffer.alloc(10);
190	      header[1] = 127;
191	      header.writeBigUInt64BE(BigInt(len), 2);
192	    }
193	    header[0] = 0x80 | opcode; // FIN + opcode
194	
195	    if (this.maskOut) {
196	      header[1] |= 0x80;
197	      const mask = randomBytes(4);
198	      const masked = Buffer.allocUnsafe(len);
199	      for (let i = 0; i < len; i++) masked[i] = payload[i] ^ mask[i & 3];
200	      this.socket.write(Buffer.concat([header, mask, masked]));
201	    } else {
202	      this.socket.write(Buffer.concat([header, payload]));
203	    }
204	  }
205	
206	  /** Public: forward an application message (preserves text/binary opcode). */
207	  send(opcode, payload) {
208	    this._send(opcode === 0x1 ? 0x1 : 0x2, payload);
209	  }
210	
211	  close() {
212	    if (this.closed) {
213	      try {
214	        this.socket.destroy();
215	      } catch {}
216	      return;
217	    }
218	    try {
219	      this._send(0x8, Buffer.alloc(0));
220	    } catch {}
221	    try {
222	      this.socket.end();
223	    } catch {}
224	    this._fireClose();
225	  }
226	}
