/**
 * name.com API v4 client (reseller). Auth: HTTP Basic (username:token).
 * Production: https://api.name.com  ·  Dev/sandbox: https://api.dev.name.com
 */

import { SANDBOX } from "./sandbox";

export function registrarConfigured(): boolean {
  return !!(process.env.NAMECOM_USERNAME && process.env.NAMECOM_TOKEN);
}

/**
 * Inbound transfers additionally work in SANDBOX (staging) with synthetic
 * results, so the whole transfer-in flow — quote, submit, poll, cancel — can be
 * exercised end to end without touching the registrar or a real domain.
 */
export function transfersAvailable(): boolean {
  return SANDBOX || registrarConfigured();
}

function baseUrl(): string {
  return process.env.NAMECOM_ENV === "dev" ? "https://api.dev.name.com" : "https://api.name.com";
}

function authHeader(): string {
  const raw = `${process.env.NAMECOM_USERNAME}:${process.env.NAMECOM_TOKEN}`;
  return "Basic " + Buffer.from(raw).toString("base64");
}

async function nc(
  method: string,
  path: string,
  body?: unknown,
  opts?: { nullOn404?: boolean }
): Promise<any> {
  if (!registrarConfigured()) throw new Error("Domain registrar (name.com) is not configured");
  const res = await fetch(`${baseUrl()}${path}`, {
    method,
    headers: { Authorization: authHeader(), "Content-Type": "application/json" },
    body: body ? JSON.stringify(body) : undefined,
    signal: AbortSignal.timeout(30_000),
  });
  const text = await res.text();
  let json: any = {};
  try {
    json = text ? JSON.parse(text) : {};
  } catch {
    /* non-JSON error body */
  }
  if (!res.ok) {
    // Some callers treat "absent" as a normal answer (e.g. polling a transfer
    // that has already dropped off the registrar's list) — let them opt in to a
    // null instead of an exception rather than string-matching an error message.
    if (opts?.nullOn404 && res.status === 404) return null;
    const msg = json?.message || json?.details || text || `HTTP ${res.status}`;
    throw new Error(`name.com: ${msg}`);
  }
  return json;
}

const dollarsToCents = (d: number | undefined) => (d === undefined ? null : Math.round(d * 100));

/** Platform markup added to the registrar cost, as a percentage (admin-tunable via env). */
export function domainMarkupPct(): number {
  return Number(process.env.DOMAIN_MARKUP_PCT ?? 25);
}

/** Retail (customer) price for a given registrar cost, markup applied. */
export function retailCents(costCents: number | null): number | null {
  if (costCents === null) return null;
  return Math.round(costCents * (1 + domainMarkupPct() / 100));
}

