export async function checkDomains(domains: string[]): Promise<DomainCheck[]> {
  const json = await nc("POST", "/v4/domains:checkAvailability", { domainNames: domains });
  return (json.results ?? []).map((r: any) => {
    const cost = dollarsToCents(r.purchasePrice);
    const renewCost = dollarsToCents(r.renewalPrice ?? r.purchasePrice);
    return {
      domain: r.domainName,
      available: r.purchasable === true,
      premium: r.premium === true,
      priceCents: retailCents(cost),
      costCents: cost,
      renewCents: retailCents(renewCost),
    };
  });
}

export type RegistrantContact = {
  firstName: string;
  lastName: string;
  address1: string;
  city: string;
  stateProvince: string;
  postalCode: string;
  country: string; // ISO-2
  phone: string; // +NN.NNNNNNNNNN
  email: string;
};

function ncContact(c: RegistrantContact) {
  return {
    firstName: c.firstName,
    lastName: c.lastName,
    address1: c.address1,
    city: c.city,
    state: c.stateProvince,
    zip: c.postalCode,
    country: c.country,
    phone: c.phone,
    email: c.email,
  };
}

/** Registers for `years` at the given expected price (from checkDomains). */
export async function registerDomain(
  domain: string,
  years: number,
  contact: RegistrantContact,
  purchaseCents: number
): Promise<{ expiresAt?: Date }> {
  const c = ncContact(contact);
  const json = await nc("POST", "/v4/domains", {
    domain: {
      domainName: domain,
      contacts: { registrant: c, admin: c, tech: c, billing: c },
      privacyEnabled: true,
    },
    purchasePrice: purchaseCents / 100,
    years,
  });
  const exp = json?.domain?.expireDate ?? json?.order?.expireDate;
  return { expiresAt: exp ? new Date(exp) : undefined };
}

export async function renewDomain(domain: string, years: number, purchaseCents: number): Promise<void> {
  await nc("POST", `/v4/domains/${encodeURIComponent(domain)}:renew`, {
    purchasePrice: purchaseCents / 100,
    years,
  });
}

export async function domainInfo(domain: string): Promise<{ expires?: Date; created?: Date }> {
  const json = await nc("GET", `/v4/domains/${encodeURIComponent(domain)}`);
  return {
    expires: json?.expireDate ? new Date(json.expireDate) : undefined,
    created: json?.createDate ? new Date(json.createDate) : undefined,
  };
}

// ---------- Inbound transfers (transfer-in) ----------
//
// name.com v4 transfers:
//   POST /v4/transfers                      { domainName, authCode, privacyEnabled, purchasePrice }
//   GET  /v4/transfers                      -> { transfers: [...] }
//   GET  /v4/transfers/{domainName}         -> { domainName, email, status }
//   POST /v4/transfers/{domainName}:cancel  -> { domainName, email, status }
//
// A transfer always includes a 1-year extension of the registration, which is
// why it is priced off the TLD's RENEWAL rate rather than its promo/first-year
// registration rate.

/** Compressed sandbox timeline (real transfers take 5-7 days — see SANDBOX_* notes). */
const SANDBOX_APPROVAL_MS = 2 * 60_000;
const SANDBOX_REGISTRY_MS = 5 * 60_000;

/** Deterministic synthetic per-year cost for a TLD in sandbox (integer cents). */
function sandboxTldCostCents(domain: string): number {
  const tld = domain.slice(domain.lastIndexOf(".") + 1);
  let h = 0;
  for (const ch of tld) h = (h * 31 + ch.charCodeAt(0)) % 997;
  return 900 + (h % 21) * 50; // $9.00 – $19.00
}

