/* ------------------------------------------------------------------ *
 * URL forwarding / redirects (name.com URL-forwarding API).
 *   GET/POST/DELETE /v4/domains/{domain}/url/forwarding[/{host}]
 * Degrades to a persisted-intent Setting + note when unconfigured.
 * ------------------------------------------------------------------ */

export type Redirect = { host: string; forwardsTo: string; type: string };

const redirectStoreKey = (domainId: string) => `domain-redirect:${domainId}`;

async function readRedirectIntent(domainId: string): Promise<Redirect[]> {
  const s = await db.setting.findUnique({ where: { key: redirectStoreKey(domainId) } });
  if (!s?.value) return [];
  try {
    const parsed = JSON.parse(s.value);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

async function writeRedirectIntent(domainId: string, list: Redirect[]): Promise<void> {
  await db.setting.upsert({
    where: { key: redirectStoreKey(domainId) },
    create: { key: redirectStoreKey(domainId), value: JSON.stringify(list) },
    update: { value: JSON.stringify(list) },
  });
}

export type RedirectsView = { forwards: Redirect[]; live: boolean; note?: string; error?: string };

/** List forwardings — live from name.com when possible, else persisted intent. */
export async function listRedirects(domainId: string): Promise<RedirectsView> {
  let ctx;
  try {
    ctx = await ownedDomain(domainId);
  } catch (e) {
    return { forwards: [], live: false, error: errMsg(e) };
  }
  if (ctx.domain.status === "ACTIVE" && registrarConfigured()) {
    try {
      const json = await nc("GET", `/v4/domains/${encodeURIComponent(ctx.domain.name)}/url/forwarding`);
      const forwards: Redirect[] = (json.urlForwarding ?? json.urlForwardings ?? []).map((f: any) => ({
        host: f.host ?? "",
        forwardsTo: f.forwardsTo ?? "",
        type: f.type ?? "redirect301",
      }));
      return { forwards, live: true };
    } catch (e) {
      // Fall back to intent store but tell the truth about why.
      const forwards = await readRedirectIntent(domainId);
      return { forwards, live: false, note: `Live forwarding unavailable (${errMsg(e)}); showing saved intent.` };
    }
  }
  const forwards = await readRedirectIntent(domainId);
  return { forwards, live: false, note: "Registrar not connected — showing saved intent that will apply once live." };
}

const REDIRECT_TYPES = ["redirect301", "redirect302", "masked"] as const;

export async function setRedirect(
  domainId: string,
  hostRaw: string,
  forwardsTo: string,
  type: string
): Promise<RedirectsView> {
  let ctx;
  try {
    ctx = await ownedDomain(domainId);
  } catch (e) {
    return { forwards: [], live: false, error: errMsg(e) };
  }
  const host = normHost(hostRaw);
  const t = (REDIRECT_TYPES as readonly string[]).includes(type) ? type : "redirect301";
  const url = z.string().url().max(2000).safeParse(forwardsTo.trim());
  if (!url.success) return { ...(await listRedirects(domainId)), error: "Enter a valid destination URL (including https://)." };

  const canLive = ctx.domain.status === "ACTIVE" && registrarConfigured();
  if (canLive) {
    try {
      // Upsert: delete any existing forwarding for this host, then create.
      try {
        await nc("DELETE", `/v4/domains/${encodeURIComponent(ctx.domain.name)}/url/forwarding/${encodeURIComponent(host)}`);
      } catch {
        /* none existed */
      }
      await nc("POST", `/v4/domains/${encodeURIComponent(ctx.domain.name)}/url/forwarding`, {
        host,
        forwardsTo: url.data,
        type: t,
      });
    } catch (e) {
      return { ...(await listRedirects(domainId)), error: `Registrar rejected the redirect: ${errMsg(e)}` };
    }
  } else {
    const list = (await readRedirectIntent(domainId)).filter((r) => normHost(r.host) !== host);
    list.push({ host, forwardsTo: url.data, type: t });
    await writeRedirectIntent(domainId, list);
  }

  await db.auditLog.create({
    data: { userId: ctx.user.id, action: "domain.redirect_set", detail: `${ctx.domain.name} ${host || "@"} -> ${url.data} (${t})${canLive ? " live" : " intent"}` },
  });
  revalidatePath(`/dashboard/domains/${domainId}`);
  const view = await listRedirects(domainId);
  return {
    ...view,
    note: canLive
      ? "Redirect saved at name.com via URL forwarding. It can take a little while to take effect."
      : "Saved. This redirect will be applied via name.com URL forwarding once the domain is active and the registrar is connected.",
  };
}

export async function deleteRedirect(domainId: string, hostRaw: string): Promise<RedirectsView> {
  let ctx;
  try {
    ctx = await ownedDomain(domainId);
  } catch (e) {
    return { forwards: [], live: false, error: errMsg(e) };
  }
  const host = normHost(hostRaw);
  const canLive = ctx.domain.status === "ACTIVE" && registrarConfigured();
  if (canLive) {
    try {
      await nc("DELETE", `/v4/domains/${encodeURIComponent(ctx.domain.name)}/url/forwarding/${encodeURIComponent(host)}`);
    } catch (e) {
      return { ...(await listRedirects(domainId)), error: `Could not remove redirect: ${errMsg(e)}` };
    }
  }
  const list = (await readRedirectIntent(domainId)).filter((r) => normHost(r.host) !== host);
  await writeRedirectIntent(domainId, list);
  await db.auditLog.create({
    data: { userId: ctx.user.id, action: "domain.redirect_delete", detail: `${ctx.domain.name} ${host || "@"}` },
  });
  revalidatePath(`/dashboard/domains/${domainId}`);
  return { ...(await listRedirects(domainId)), note: "Redirect removed." };
}

/* ------------------------------------------------------------------ *
 * Registrar lock (name.com :lock / :unlock). Persist state + note.
 * ------------------------------------------------------------------ */

const lockStoreKey = (domainId: string) => `domain-lock:${domainId}`;

export type LockView = { locked: boolean; live: boolean; note?: string; error?: string };

export async function getRegistrarLock(domainId: string): Promise<LockView> {
  let ctx;
  try {
    ctx = await ownedDomain(domainId);
  } catch (e) {
    return { locked: false, live: false, error: errMsg(e) };
  }
  if (ctx.domain.status === "ACTIVE" && registrarConfigured()) {
    try {
      const json = await nc("GET", `/v4/domains/${encodeURIComponent(ctx.domain.name)}`);
      const locked = json?.locked === true;
      return { locked, live: true };
    } catch {
      /* fall through to stored intent */
    }
  }
  const s = await db.setting.findUnique({ where: { key: lockStoreKey(domainId) } });
  return { locked: s?.value === "true", live: false };
}

export async function setRegistrarLock(domainId: string, locked: boolean): Promise<LockView> {
  let ctx;
  try {
    ctx = await ownedDomain(domainId);
  } catch (e) {
    return { locked: false, live: false, error: errMsg(e) };
  }
  const canLive = ctx.domain.status === "ACTIVE" && registrarConfigured();
  let live = false;
  let note: string | undefined;
  if (canLive) {
    try {
      await nc("POST", `/v4/domains/${encodeURIComponent(ctx.domain.name)}:${locked ? "lock" : "unlock"}`, {});
      live = true;
      note = locked
        ? "Registrar lock enabled — the domain is protected against unauthorized transfers."
        : "Registrar lock disabled — the domain can now be transferred to another registrar.";
    } catch (e) {
      return { locked: !locked, live: false, error: `Registrar rejected the change: ${errMsg(e)}. Some TLDs manage the lock manually.` };
    }
  } else {
    note = "Saved. This lock preference will be applied at name.com once the domain is active and the registrar is connected.";
  }
  await db.setting.upsert({
    where: { key: lockStoreKey(domainId) },
    create: { key: lockStoreKey(domainId), value: String(locked) },
    update: { value: String(locked) },
  });
  await db.auditLog.create({
    data: { userId: ctx.user.id, action: "domain.registrar_lock", detail: `${ctx.domain.name} -> ${locked ? "locked" : "unlocked"}${live ? " (live)" : ""}` },
  });
  revalidatePath(`/dashboard/domains/${domainId}`);
  return { locked, live, note };
}

