114	 * Submit an inbound transfer.
115	 *
116	 * ORDER MATTERS — the registrar is called BEFORE any money moves:
117	 *   1. re-quote server-side (the price the client showed is never trusted),
118	 *   2. `createTransfer` at the registrar,
119	 *   3. debit + invoice + Domain row, all in ONE transaction.
120	 *
121	 * So a charge for a transfer that was never submitted is structurally
122	 * impossible. A double charge is impossible three ways over: the in-process
123	 * guard blocks the double-click, `Domain.name` is UNIQUE inside the charging
124	 * transaction (and the retry path CAS-swaps off the exact status we read), and
125	 * name.com itself refuses a second transfer for a domain already in flight.
126	 *
127	 * If the debit fails after a successful submit (balance drained in the seconds
128	 * between the check and the charge) we cancel the transfer back out at the
129	 * registrar rather than quietly performing work nobody paid for.
130	 */
131	export async function submitTransferIn(prev: any, formData: FormData): Promise<{ error?: string }> {
