25	/**
26	 * A hostname we are willing to publish: a valid FQDN of 2+ labels, lowercase,
27	 * no scheme, no port, no trailing dot, no wildcard. Mirrors lib/ssh-exec DOMAIN_RE
28	 * but is kept local so this module has no SSH dependency.
29	 */
30	const HOSTNAME_RE = /^(?=.{1,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,24}$/;
31	
32	/** Normalise + validate a hostname. Returns null when it isn't publishable. */
33	export function cleanHostname(input: unknown): string | null {
34	  const h = String(input ?? "")
35	    .trim()
36	    .toLowerCase()
37	    .replace(/\.$/, "");
38	  if (!h || h.length > 253) return null;
39	  if (!HOSTNAME_RE.test(h)) return null;
40	  return h;
41	}
