57	 * (example.co.uk) and a delegated sub-zone both resolve correctly without us
58	 * shipping a public-suffix list. Capped so one call is at most a few lookups.
59	 */
60	export function zoneCandidates(hostname: string): string[] {
61	  const labels = hostname.split(".");
62	  const out: string[] = [];
63	  for (let i = labels.length - 2; i >= 0 && out.length < 4; i--) {
64	    const candidate = labels.slice(i).join(".");
65	    if (candidate.split(".").length >= 2) out.push(candidate);
66	  }
67	  // Most specific first: labels.slice(i) grows as i shrinks, so reverse.
68	  return out.reverse();
69	}
