97	export async function pointHostnameToIp(opts: {
98	  user: { id: string; cloudflareTokenEnc: string | null };
99	  hostname: string;
100	  ip: string | null | undefined;
101	}): Promise<PointDnsResult> {
102	  const hostname = cleanHostname(opts.hostname);
103	  if (!hostname) {
104	    return { ok: false, error: "Enter a valid domain or subdomain (e.g. example.com)." };
105	  }
106	
107	  const ip = String(opts.ip ?? "").trim();
108	  if (!isIpv4(ip)) {
109	    return {
110	      ok: false,
111	      error: "This server doesn't have a public IPv4 address yet — try again once it's finished provisioning.",
