123	      ok: true,
124	      hostname,
125	      ip,
126	      zone: labels.slice(-2).join("."),
127	      action: "created",
128	      simulated: true,
129	    };
130	  }
131	
132	  // Find which zone in the account owns this hostname (most specific first).
133	  let zoneId: string | null = null;
134	  let zone = "";
