// Cloudflare DNS API client (API-token auth).
//
// Plain server-side module (NO "use server") — safe to import from server
// actions and the worker; never bundled to the client. Talks to the Cloudflare
// v4 REST API using a customer-supplied API token (scoped to Zone → DNS → Edit
// for their zone). The token is passed in per call — this module never reads it
// from the environment or persists it.
//
// Every function throws a clear CloudflareError on a non-success response so
// callers can surface a friendly message; callers that must stay tolerant wrap
// these in try/catch.

const CF_API = "https://api.cloudflare.com/client/v4";

export class CloudflareError extends Error {
  constructor(
    message: string,
    public status?: number,
    public code?: number,
  ) {
    super(message);
    this.name = "CloudflareError";
  }
}

type CfEnvelope<T> = {
  success: boolean;
  errors?: { code: number; message: string }[];
  result: T;
};

/** Core request helper — attaches the bearer token, parses the v4 envelope and
 * throws CloudflareError on transport failure or a `success:false` payload. */
async function cfRequest<T>(
  token: string,
  method: "GET" | "POST" | "PUT",
  path: string,
  body?: unknown,
): Promise<T> {
  const url = `${CF_API}${path.startsWith("/") ? path : `/${path}`}`;

  let res: Response;
  try {
    res = await fetch(url, {
      method,
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json",
        Accept: "application/json",
      },
      body: body === undefined ? undefined : JSON.stringify(body),
      cache: "no-store",
    });
  } catch (e) {
    throw new CloudflareError(
      `Cloudflare unreachable (${method} ${path}): ${e instanceof Error ? e.message : String(e)}`,
    );
  }

  const text = await res.text();
  let parsed: CfEnvelope<T> | null = null;
  try {
    parsed = text ? (JSON.parse(text) as CfEnvelope<T>) : null;
  } catch {
    // fall through to a generic error below
  }

  if (!parsed || parsed.success !== true) {
    const first = parsed?.errors?.[0];
    // 403/9109 → token lacks permission or is invalid; surface a stable message.
    const msg = first?.message ?? `Cloudflare ${method} ${path} -> HTTP ${res.status}`;
    throw new CloudflareError(msg, res.status, first?.code);
  }

  return parsed.result;
}

/**
 * Confirm an API token is valid and active (`GET /user/tokens/verify`). Returns
 * true only when Cloudflare reports the token status as "active". Never throws
 * for an ordinary invalid/expired token — returns false — but rethrows a genuine
 * transport failure so the caller can distinguish "rejected" from "unreachable".
 */
export async function cfVerifyToken(token: string): Promise<boolean> {
  try {
    const result = await cfRequest<{ status?: string }>(token, "GET", "/user/tokens/verify");
    return String(result?.status ?? "").toLowerCase() === "active";
  } catch (e) {
    if (e instanceof CloudflareError && (e.status === 400 || e.status === 401 || e.status === 403)) {
      return false;
    }
    throw e;
  }
}

/**
 * Resolve a zone name (registrable domain) to its Cloudflare zone id, or null
 * when the token can't see a zone by that exact name. `GET /zones?name=<zone>`.
 */
export async function cfFindZoneId(token: string, zoneName: string): Promise<string | null> {
  const name = zoneName.trim().toLowerCase().replace(/\.$/, "");
  const result = await cfRequest<{ id: string; name: string }[]>(
    token,
    "GET",
    `/zones?name=${encodeURIComponent(name)}&status=active&per_page=5`,
  );
  const zone = Array.isArray(result)
    ? result.find((z) => z.name?.toLowerCase() === name) ?? result[0]
    : undefined;
  return zone?.id ?? null;

