70	/**
71	 * Run one command on an already-connected ssh2 client, capturing stdout/stderr
72	 * and the exit code. Rejects on transport error or if the command exceeds
73	 * `timeoutMs` (the channel is torn down so a hung certbot can't wedge the worker).
74	 */
75	function sshExec(conn: SshClient, command: string, timeoutMs: number): Promise<SshResult> {
76	  return new Promise((resolve, reject) => {
77	    conn.exec(command, (err, stream) => {
78	      if (err) return reject(err);
79	      let stdout = "";
80	      let stderr = "";
81	      let settled = false;
82	      const timer = setTimeout(() => {
83	        if (settled) return;
84	        settled = true;
85	        try {
86	          stream.close();
87	        } catch {
88	          /* best effort */
89	        }
90	        reject(new Error(`Command timed out after ${Math.round(timeoutMs / 1000)}s`));
91	      }, timeoutMs);
92	
93	      stream
94	        .on("close", (code: number | null) => {
95	          if (settled) return;
96	          settled = true;
97	          clearTimeout(timer);
98	          resolve({ code, stdout, stderr });
99	        })
100	        .on("data", (d: Buffer) => {
101	          stdout += d.toString("utf8");
102	        })
103	        .stderr.on("data", (d: Buffer) => {
104	          stderr += d.toString("utf8");
105	        });
106	    });
107	  });
108	}
