197	  }
198	  const rootPassword = serverRootPassword(server);
199	  if (!rootPassword) throw new Error("Server has no root password set.");
200	
201	  const qDomain = shellQuote(domain);
202	  const qEmail = shellQuote(CERTBOT_EMAIL);
203	
204	  return withSsh(target, rootPassword, async (conn) => {
205	    // 1. Ensure certbot is present. `command -v` is portable; install only if missing.
206	    const have = await sshExec(conn, "command -v certbot >/dev/null 2>&1 && echo yes || echo no", PROBE_TIMEOUT_MS);
207	    if (have.stdout.trim() !== "yes") {
208	      // Pick the installer from whichever package manager exists.
209	      const pm = await sshExec(
210	        conn,
211	        "if command -v apt-get >/dev/null 2>&1; then echo apt; " +
212	          "elif command -v dnf >/dev/null 2>&1; then echo dnf; else echo none; fi",
213	        PROBE_TIMEOUT_MS
214	      );
215	      const which = pm.stdout.trim();
216	      let installCmd: string;
217	      if (which === "apt") {
218	        installCmd = "DEBIAN_FRONTEND=noninteractive apt-get update -y && apt-get install -y certbot";
219	      } else if (which === "dnf") {
220	        installCmd = "dnf install -y certbot";
221	      } else {
222	        throw new Error("No supported package manager (apt-get/dnf) found to install certbot.");
223	      }
224	      const inst = await sshExec(conn, installCmd, CERTBOT_TIMEOUT_MS);
225	      if (inst.code !== 0) {
226	        throw new Error(`certbot install failed: ${(inst.stderr || inst.stdout).trim().slice(0, 300)}`);
227	      }
228	      // Re-check that certbot is now on PATH.
229	      const recheck = await sshExec(conn, "command -v certbot >/dev/null 2>&1 && echo yes || echo no", PROBE_TIMEOUT_MS);
230	      if (recheck.stdout.trim() !== "yes") {
231	        throw new Error("certbot still not available after install.");
232	      }
