281	export async function sslIssue(job: Job): Promise<void> {
282	  const payload = (job.payload ?? {}) as { certId?: string };
283	  if (!payload.certId) throw new Error("ssl job: missing certId");
284	
285	  const cert = await db.sslCertificate.findUnique({ where: { id: payload.certId } });
286	  if (!cert) throw new Error(`SslCertificate ${payload.certId} not found`);
287	
288	  // Mark in-flight so the UI shows "issuing" while we work.
289	  await db.sslCertificate.update({ where: { id: cert.id }, data: { status: "ISSUING" } });
290	
291	  try {
292	    // ---------------------------------------------------------------------
293	    // Real issuance path (SSH + certbot). Guarded so it can never run by
294	    // accident: it happens ONLY when ENABLE_REAL_SSL is explicitly set AND we
295	    // are not in SANDBOX. In every other case we fall through to the simulated
296	    // success below (the default, and what SANDBOX/staging requires).
297	    //
298	    // The real path (issueRealCertificate) SSHes into the customer's own VM —
299	    // host/port/root/password derived exactly like lib/sftp — and runs:
300	    //   certbot certonly --standalone -n --agree-tos -m <email> -d <domain>
301	    // installing certbot first if needed and reading the real notAfter back.
302	    // ---------------------------------------------------------------------
303	    const realIssuanceEnabled = !SANDBOX && process.env.ENABLE_REAL_SSL === "1";
304	    if (realIssuanceEnabled) {
305	      const { issuedAt, expiresAt } = await issueRealCertificate(cert);
306	      await db.sslCertificate.update({
307	        where: { id: cert.id },
308	        data: { status: "ACTIVE", issuedAt, expiresAt, lastError: null },
309	      });
310	      await notify(
311	        cert.userId,
312	        `SSL certificate issued for ${cert.domain}`,
313	        "Your Let's Encrypt certificate is active.",
314	        "/dashboard/ssl"
315	      );
316	      return;
317	    }
318	
319	    // Simulation is a SANDBOX affordance and MUST NEVER run in production.
320	    //
321	    // Until 2026-07-25 it did: production has no ENABLE_REAL_SSL, so every real
322	    // customer request fell through to the block below, which wrote status
323	    // "ACTIVE" with an invented 90-day expiry and told them "your Let's Encrypt
324	    // certificate is active" — while no certbot had run and no certificate
325	    // existed. Identical in kind to the migration reporting "Sites serving: 4/4"
326	    // with six domains dark: the system asserting an outcome it never verified.
327	    //
328	    // A certificate we did not issue is a FAILURE, and it must say so loudly
329	    // enough that an operator notices the flag is missing.
330	    if (!SANDBOX) {
331	      throw new Error(
332	        "Certificate issuance is switched off on this server (ENABLE_REAL_SSL is not set), " +
333	          "so no certificate was requested from Let's Encrypt. Nothing was installed — " +
334	          "this certificate is NOT active. Ask support to enable real issuance."
335	      );
336	    }
337	
338	    // Default: simulated success (SANDBOX-only, no SSH, no certbot).
339	    const now = new Date();
340	    await db.sslCertificate.update({
341	      where: { id: cert.id },
342	      data: {
343	        status: "ACTIVE",
344	        issuedAt: now,
345	        expiresAt: new Date(now.getTime() + CERT_LIFETIME_MS),
346	        lastError: null,
347	      },
348	    });
349	    await notify(
350	      cert.userId,
351	      `SSL certificate issued for ${cert.domain}`,
352	      "Your Let's Encrypt certificate is active and valid for 90 days (sandbox).",
353	      "/dashboard/ssl"
354	    );
355	  } catch (e: any) {
356	    const reason = String(e?.message ?? e).slice(0, 500);
357	    await db.sslCertificate.update({
358	      where: { id: cert.id },
359	      data: { status: "FAILED", lastError: reason },
360	    });
361	    await notify(
362	      cert.userId,
363	      `SSL certificate failed for ${cert.domain}`,
364	      reason.slice(0, 200),
365	      "/dashboard/ssl"
366	    );
367	  }
368	}
