1	/**
2	 * Inline (non-worker) quick reads for the control panel: service status and a
3	 * live process/resource snapshot. These are cheap, read-only SSH commands with a
4	 * short timeout, so they run inline from the server actions rather than via a
5	 * queued job (mirrors how lib/sftp.ts serves file listings inline).
6	 *
7	 * SANDBOX: on staging NO real SSH is ever opened — every read returns realistic,
8	 * deterministic synthetic data so the whole panel UX works end to end without a
9	 * live VM. Plain server module (no "use server"): imported by lib/actions-cron.ts.
10	 */
11	import { SANDBOX } from "./sandbox";
12	import { withServerSsh, exec, assertService, shellQuote, QUICK_TIMEOUT_MS } from "./ssh-exec";
13	import { COMMON_SERVICES, type ServiceStatus, type ProcessSnapshot } from "./cpanel-types";
14	import type { SftpServer } from "./sftp";
15	
16	/** Deterministic pseudo-random in [0,1) from a string seed (sandbox realism). */
17	function seeded(seed: string): number {
18	  let h = 2166136261;
19	  for (let i = 0; i < seed.length; i++) {
20	    h ^= seed.charCodeAt(i);
21	    h = Math.imul(h, 16777619);
22	  }
23	  return ((h >>> 0) % 10000) / 10000;
24	}
25	
26	// ---------------------------------------------------------------------------
27	// Service status
28	// ---------------------------------------------------------------------------
29	
30	/**
31	 * Status of the common services. In sandbox, nginx/ssh look running, php-fpm/
32	 * mysql installed-and-running, the rest a deterministic mix. On prod we ask
33	 * systemd for each unit in one round-trip.
34	 */
35	export async function readServiceStatuses(server: SftpServer): Promise<ServiceStatus[]> {
36	  if (SANDBOX) {
37	    return COMMON_SERVICES.map((s) => {
38	      let state: ServiceStatus["state"];
39	      if (s.unit === "nginx" || s.unit === "ssh") state = "running";
40	      else if (s.unit === "php-fpm" || s.unit === "mysql") state = "running";
41	      else state = seeded(server.id + s.unit) > 0.5 ? "running" : "not-installed";
42	      return { unit: s.unit, label: s.label, state };
43	    });
44	  }
45	
46	  return withServerSsh(server, async (conn) => {
47	    const out: ServiceStatus[] = [];
48	    for (const s of COMMON_SERVICES) {
49	      assertService(s.unit);
50	      const q = shellQuote(s.unit);
51	      // is-active prints active/inactive/failed/unknown; if the unit doesn't
52	      // exist at all, `systemctl list-unit-files` finds nothing → not-installed.
53	      const r = await exec(
54	        conn,
55	        `if systemctl list-unit-files ${q}.service >/dev/null 2>&1 || systemctl status ${q} >/dev/null 2>&1; then ` +
56	          `systemctl is-active ${q} 2>/dev/null || echo inactive; else echo missing; fi`,
57	        QUICK_TIMEOUT_MS
58	      );
59	      const v = r.stdout.trim();
60	      let state: ServiceStatus["state"];
61	      if (v === "active") state = "running";
62	      else if (v === "missing") state = "not-installed";
63	      else if (v === "inactive" || v === "failed") state = "stopped";
64	      else state = "unknown";
65	      out.push({ unit: s.unit, label: s.label, state });
66	    }
67	    return out;
68	  });
69	}
70	
71	// ---------------------------------------------------------------------------
72	// Process / resource snapshot
73	// ---------------------------------------------------------------------------
74	
75	const SANDBOX_COMMANDS = [
76	  "nginx: worker process",
77	  "php-fpm: pool www",
78	  "mysqld",
79	  "node /var/www/app/server.js",
80	  "redis-server *:6379",
81	  "systemd --user",
82	  "sshd: root@pts/0",
83	];
84	
85	export async function readProcessSnapshot(server: SftpServer): Promise<ProcessSnapshot> {
86	  if (SANDBOX) {
87	    const base = seeded(server.id);
88	    const cpuPct = Math.round((15 + base * 55) * 10) / 10;
89	    const memTotalMB = 4096;
90	    const memUsedMB = Math.round(memTotalMB * (0.35 + base * 0.4));
91	    const diskTotalGB = 80;
92	    const diskUsedGB = Math.round(diskTotalGB * (0.2 + base * 0.5) * 10) / 10;
93	    const top = SANDBOX_COMMANDS.map((command, i) => ({
94	      pid: 400 + i * 137 + Math.floor(seeded(server.id + i) * 90),
95	      user: i % 3 === 0 ? "root" : "www-data",
96	      cpu: Math.round(seeded(server.id + "c" + i) * 40 * 10) / 10,
97	      mem: Math.round(seeded(server.id + "m" + i) * 12 * 10) / 10,
98	      command,
99	    }))
100	      .sort((a, b) => b.cpu - a.cpu)
101	      .slice(0, 6);
102	    return {
103	      cpuPct,
104	      memUsedMB,
105	      memTotalMB,
106	      diskUsedGB,
107	      diskTotalGB,
108	      loadAvg: [
109	        Math.round(base * 2 * 100) / 100,
110	        Math.round(base * 1.6 * 100) / 100,
111	        Math.round(base * 1.2 * 100) / 100,
112	      ],
113	      uptimeSec: Math.floor(3600 * 24 * (2 + base * 20)),
114	      top,
115	    };
116	  }
117	
118	  return withServerSsh(server, async (conn) => {
119	    // One fixed command bundle — no user input anywhere. Emits labelled lines we
120	    // parse below; robust to missing tools (best-effort fields).
121	    const script =
122	      "echo '#LOAD'; cat /proc/loadavg 2>/dev/null; " +
123	      "echo '#UP'; cat /proc/uptime 2>/dev/null; " +
124	      "echo '#MEM'; free -m 2>/dev/null | awk '/^Mem:/{print $2, $3}'; " +
125	      "echo '#DISK'; df -BG / 2>/dev/null | awk 'NR==2{gsub(/G/,\"\"); print $2, $3}'; " +
126	      "echo '#CPU'; awk '/^cpu /{u=$2+$4; t=$2+$4+$5; print u, t}' /proc/stat 2>/dev/null; " +
127	      "echo '#TOP'; ps -eo pid,user,pcpu,pmem,comm --sort=-pcpu 2>/dev/null | head -n 8";
128	    const r = await exec(conn, script, QUICK_TIMEOUT_MS);
129	    return parseSnapshot(r.stdout);
130	  });
131	}
132	
133	/** Parse the labelled snapshot output into a ProcessSnapshot (best-effort). */
134	function parseSnapshot(out: string): ProcessSnapshot {
135	  const sections: Record<string, string[]> = {};
136	  let cur = "";
137	  for (const raw of out.split("\n")) {
138	    const line = raw.trimEnd();
139	    if (line.startsWith("#")) {
140	      cur = line.slice(1);
141	      sections[cur] = [];
142	    } else if (cur && line.trim().length) {
143	      sections[cur].push(line);
144	    }
145	  }
146	  const num = (s: string | undefined, d = 0) => {
147	    const n = Number(s);
148	    return Number.isFinite(n) ? n : d;
149	  };
150	
151	  const load = (sections.LOAD?.[0] ?? "").split(/\s+/);
152	  const loadAvg: [number, number, number] = [num(load[0]), num(load[1]), num(load[2])];
153	  const uptimeSec = Math.floor(num((sections.UP?.[0] ?? "").split(/\s+/)[0]));
154	  const mem = (sections.MEM?.[0] ?? "").split(/\s+/);
155	  const memTotalMB = num(mem[0], 1);
156	  const memUsedMB = num(mem[1]);
157	  const disk = (sections.DISK?.[0] ?? "").split(/\s+/);
158	  const diskTotalGB = num(disk[0], 1);
159	  const diskUsedGB = num(disk[1]);
160	  const cpu = (sections.CPU?.[0] ?? "").split(/\s+/);
161	  const cpuBusy = num(cpu[0]);
162	  const cpuTotal = num(cpu[1], 1);
163	  const cpuPct = Math.round(Math.min(100, (cpuBusy / cpuTotal) * 100) * 10) / 10;
164	
165	  const top = (sections.TOP ?? [])
166	    .filter((l) => !/^\s*PID\b/i.test(l))
167	    .map((l) => {
168	      const p = l.trim().split(/\s+/);
169	      return {
170	        pid: num(p[0]),
171	        user: p[1] ?? "?",
172	        cpu: num(p[2]),
173	        mem: num(p[3]),
174	        command: p.slice(4).join(" ") || "?",
175	      };
176	    })
177	    .slice(0, 6);
178	
179	  return { cpuPct, memUsedMB, memTotalMB, diskUsedGB, diskTotalGB, loadAvg, uptimeSec, top };
180	}
